import pulp

prob = pulp.LpProblem("Preemptive_Goal_Programming", pulp.LpMinimize)

# Decision variables x_ijk
x = {}
for i in range(1, 7):
    if i == 1:
        for j in ['D', 'N']:
            for k in [1, 2]:
                x[(i, j, k)] = pulp.LpVariable(f"x_{i}{j}{k}", lowBound=0, cat=pulp.LpInteger)
    elif i == 2:
        for j in ['D', 'N']:
            for k in [2, 3]:
                x[(i, j, k)] = pulp.LpVariable(f"x_{i}{j}{k}", lowBound=0, cat=pulp.LpInteger)
    elif i == 3:
        for j in ['D', 'N']:
            for k in [1, 3]:
                x[(i, j, k)] = pulp.LpVariable(f"x_{i}{j}{k}", lowBound=0, cat=pulp.LpInteger)
    elif i == 4:
        for j in ['D', 'N']:
            for k in [1, 3]:
                x[(i, j, k)] = pulp.LpVariable(f"x_{i}{j}{k}", lowBound=0, cat=pulp.LpInteger)
    elif i == 5:
        for j in ['D', 'N']:
            for k in [2, 3]:
                x[(i, j, k)] = pulp.LpVariable(f"x_{i}{j}{k}", lowBound=0, cat=pulp.LpInteger)
    elif i == 6:
        for j in ['D', 'N']:
            for k in [3]:
                x[(i, j, k)] = pulp.LpVariable(f"x_{i}{j}{k}", lowBound=0, cat=pulp.LpInteger)

# Deviation variables
d_minus_1 = {}
d_plus_1 = {}
for j in ['D', 'N']:
    for k in [1, 2, 3]:
        if not (j == 'D' and k == 3):
            d_minus_1[(j, k)] = pulp.LpVariable(f"d_minus_1_{j}{k}", lowBound=0, cat=pulp.LpInteger)
            d_plus_1[(j, k)] = pulp.LpVariable(f"d_plus_1_{j}{k}", lowBound=0, cat=pulp.LpInteger)

d_minus_2 = pulp.LpVariable("d_minus_2", lowBound=0, cat=pulp.LpInteger)
d_plus_2 = pulp.LpVariable("d_plus_2", lowBound=0, cat=pulp.LpInteger)
d_minus_3 = pulp.LpVariable("d_minus_3", lowBound=0, cat=pulp.LpInteger)
d_plus_3 = pulp.LpVariable("d_plus_3", lowBound=0, cat=pulp.LpInteger)

# Goal constraints P1
prob += x[(1, 'D', 1)] + x[(3, 'D', 1)] + x[(4, 'D', 1)] + d_minus_1[('D', 1)] - d_plus_1[('D', 1)] == 1000, "P1_D1"
prob += x[(1, 'D', 2)] + x[(2, 'D', 2)] + x[(5, 'D', 2)] + d_minus_1[('D', 2)] - d_plus_1[('D', 2)] == 2000, "P1_D2"
prob += x[(1, 'N', 1)] + x[(3, 'N', 1)] + x[(4, 'N', 1)] + d_minus_1[('N', 1)] - d_plus_1[('N', 1)] == 2000, "P1_N1"
prob += x[(1, 'N', 2)] + x[(2, 'N', 2)] + x[(5, 'N', 2)] + d_minus_1[('N', 2)] - d_plus_1[('N', 2)] == 1000, "P1_N2"
prob += x[(2, 'N', 3)] + x[(3, 'N', 3)] + x[(4, 'N', 3)] + x[(6, 'N', 3)] + d_minus_1[('N', 3)] - d_plus_1[('N', 3)] == 1500, "P1_N3"

# Goal constraint P2
prob += (x[(1, 'D', 1)] + x[(1, 'N', 1)] + x[(2, 'D', 2)] + x[(2, 'N', 2)] +
         x[(3, 'D', 1)] + x[(3, 'N', 1)] + x[(4, 'D', 3)] + x[(4, 'N', 3)] +
         x[(5, 'D', 3)] + x[(5, 'N', 3)] + x[(6, 'D', 3)] + x[(6, 'N', 3)] +
         d_minus_2 - d_plus_2) == 8000, "P2"

# Goal constraint P3
prob += (x[(1, 'D', 1)] + x[(1, 'D', 2)] + x[(2, 'D', 2)] + x[(2, 'D', 3)] +
         x[(5, 'D', 2)] + x[(5, 'D', 3)] + x[(3, 'N', 1)] + x[(3, 'N', 3)] +
         x[(4, 'N', 1)] + x[(4, 'N', 3)] + x[(6, 'N', 3)] + d_minus_3 - d_plus_3) == 8000, "P3"

# Supply constraints
prob += x[(1, 'D', 1)] + x[(1, 'D', 2)] + x[(1, 'N', 1)] + x[(1, 'N', 2)] <= 1500, "Supply_1"
prob += x[(2, 'D', 2)] + x[(2, 'D', 3)] + x[(2, 'N', 2)] + x[(2, 'N', 3)] <= 1500, "Supply_2"
prob += x[(3, 'D', 1)] + x[(3, 'D', 3)] + x[(3, 'N', 1)] + x[(3, 'N', 3)] <= 1500, "Supply_3"
prob += x[(4, 'D', 1)] + x[(4, 'D', 3)] + x[(4, 'N', 1)] + x[(4, 'N', 3)] <= 1500, "Supply_4"
prob += x[(5, 'D', 2)] + x[(5, 'D', 3)] + x[(5, 'N', 2)] + x[(5, 'N', 3)] <= 1500, "Supply_5"
prob += x[(6, 'D', 3)] + x[(6, 'N', 3)] <= 1500, "Supply_6"

# Objective: lexicographic with large weights
M = 10000
prob += (M * (d_minus_1[('D', 1)] + d_minus_1[('D', 2)] + d_minus_1[('N', 1)] + d_minus_1[('N', 2)] + d_minus_1[('N', 3)]) +
         M * M * d_minus_2 + M * M * M * d_minus_3)

prob.solve(pulp.PULP_CBC_CMD(msg=False, timeLimit=60))
print(f"STATUS={pulp.LpStatus[prob.status]} OBJECTIVE={pulp.value(prob.objective)}")
